-- Бонус: тот же Q16 на bench parquet_zstd, 4 прогона подряд в одной сессии Spark (1-й = холодный)
SELECT p.brand, p.type, p.size, count(DISTINCT ps.suppkey) AS supplier_cnt FROM bench.lakehouse.partsupp_parquet_zstd ps JOIN bench.lakehouse.part_parquet_zstd p ON p.partkey = ps.partkey WHERE p.brand <> 'Brand#45' AND p.type NOT LIKE 'MEDIUM POLISHED%' AND p.size IN (49, 14, 23, 45, 19, 3, 36, 9) AND ps.suppkey NOT IN (SELECT suppkey FROM bench.lakehouse.supplier_parquet_zstd WHERE comment LIKE '%Customer%Complaints%') GROUP BY p.brand, p.type, p.size ORDER BY supplier_cnt DESC, p.brand, p.type, p.size;
